ALTER POLICY "user_scoped_read" ON "users" TO public USING ("users"."id"=NULLIF(current_setting('rove.actor_id',true),'')::uuid OR "users"."id"=NULLIF(current_setting('rove.user_read',true),'')::uuid OR "users"."id"=NULLIF(current_setting('rove.quote_owner',true),'')::uuid OR EXISTS(SELECT 1 FROM public.rides r WHERE (r.rider_id="users"."id" AND r.id=NULLIF(current_setting('rove.offer_ride',true),'')::uuid) OR (((r.rider_id=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND current_setting('rove.actor_role',true)='rider' AND r.driver_id="users"."id") OR (r.driver_id=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND current_setting('rove.actor_role',true)='driver' AND r.rider_id="users"."id")) AND (r.state IN ('matched','en_route','arrived','in_progress','interrupted') OR r.updated_at>now()-interval '30 days'))) OR COALESCE(NULLIF(current_setting('rove.user_audience',true),'')::jsonb,'[]'::jsonb) ? "users"."id"::text OR "users"."subject"=NULLIF(current_setting('rove.identity_subject',true),'') OR ("users"."role"='driver' AND current_setting('rove.offer_matching',true)='true' AND NULLIF(current_setting('rove.offer_ride',true),'') IS NOT NULL));--> statement-breakpoint
ALTER POLICY "user_scoped_lock" ON "users" TO public USING (("users"."id"=NULLIF(current_setting('rove.actor_id',true),'')::uuid OR "users"."id"=NULLIF(current_setting('rove.user_read',true),'')::uuid OR "users"."id"=NULLIF(current_setting('rove.quote_owner',true),'')::uuid OR EXISTS(SELECT 1 FROM public.rides r WHERE (r.rider_id="users"."id" AND r.id=NULLIF(current_setting('rove.offer_ride',true),'')::uuid) OR (((r.rider_id=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND current_setting('rove.actor_role',true)='rider' AND r.driver_id="users"."id") OR (r.driver_id=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND current_setting('rove.actor_role',true)='driver' AND r.rider_id="users"."id")) AND (r.state IN ('matched','en_route','arrived','in_progress','interrupted') OR r.updated_at>now()-interval '30 days'))) OR COALESCE(NULLIF(current_setting('rove.user_audience',true),'')::jsonb,'[]'::jsonb) ? "users"."id"::text OR "users"."subject"=NULLIF(current_setting('rove.identity_subject',true),'') OR ("users"."role"='driver' AND current_setting('rove.offer_matching',true)='true' AND NULLIF(current_setting('rove.offer_ride',true),'') IS NOT NULL)) AND NULLIF(current_setting('rove.user_profile_write',true),'')::jsonb IS NULL AND NULLIF(current_setting('rove.user_close_write',true),'')::jsonb IS NULL) WITH CHECK (false);